  ('38021ef3-30c2-42e6-b22a-07c7a4d9e5fa', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Temsula Ao (An abridged version of the original story)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('35f3d0f9-5f00-4e57-996b-fbe9256b8960', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$profound: powerful$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('058d3a99-0280-4de3-afd3-3831c4589d23', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$revelation: a moment of realisation$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e740b220-97b0-40b6-80e2-f88008fe668b', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$The Pot Maker Check Your Understanding I Do you think Onula’s support helped Sentila? If yes, why? If no, why not?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c7fd824e-a2a3-495e-aa8e-8303c70d8a35', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$The Pot Maker Check Your Understanding II Sentila observes her mother making pots. What does this tell us about her?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('670ea8c7-8e25-4bc7-a448-b0425d89fd2e', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$had just witnessed a profound revelation in the two batches of still moist pots, standing side by side in perfect symmetry inside the shed. A new pot maker was born.$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('58d66ee7-6ab9-4f8c-94c1-98a915b10e5c', '8af718c6-ca11-482b-9d6b-832f2b767928', '833d63bc-5981-4e95-a204-12645fed36a8', 'cb2a7c44-b28f-440b-b6d4-047f1fe26154', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$41 The Pot Maker Check Your Understanding$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-14T11-05-42-601Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
